private static ThreadSnapshot parseThreadSnapshotFromLine(String line) {
	ThreadSnapshot snapshot = new ThreadSnapshot();
	try {
		String[] fields = line.split(" ");
		long timestamp = Long.parseLong(fields[0]);
		long tid = Long.parseLong(fields[1]);
		snapshot.timestamp = timestamp;
		snapshot.tid = tid;

		for (int i = 2; i < fields.length; i++) {
			if (fields[i].equals("splitting")) {
				snapshot.isSplitting = true;
			} else if (fields[i].equals("pairing")) {
				snapshot.isPairing = true;
			} else if (fields[i].startsWith("snap")) {
				snapshot.snap = Integer.parseInt(fields[i].substring(4));
			}
		}

		return snapshot;
	} catch (Exception e) {
		return null;
	}
}

